# =============================================================================
# Autonomous Source Code Sync & Verification for SatQuery Colab Runtime
# =============================================================================
import base64
import io
import os
import sys
import site
import zipfile
from pathlib import Path

# Embedded source payload
SOURCE_PAYLOAD_B64 = """"""

def sync_and_verify(workspace_path="/content/SatQuery"):
    workspace = Path(workspace_path)
    workspace.mkdir(parents=True, exist_ok=True)
    os.chdir(str(workspace))

    for p in ["/content/SatQuery", str(workspace), os.getcwd()]:
        if p not in sys.path:
            sys.path.insert(0, p)
    site.addsitedir(str(workspace))
    os.environ["PYTHONPATH"] = f"/content/SatQuery:{os.environ.get('PYTHONPATH', '')}"

    print("Syncing source tree into /content/SatQuery (preserving data/)...")

    zip_bytes = base64.b64decode(SOURCE_PAYLOAD_B64)
    with zipfile.ZipFile(io.BytesIO(zip_bytes)) as zf:
        zf.extractall(workspace)

    print("Source sync completed successfully!\n")

    # Verification checks
    print("core exists:", os.path.exists(str(workspace / "core")))
    print("specialists exists:", os.path.exists(str(workspace / "specialists")))

    from core.interfaces import BaseSpecialistTool, ValidationResult
    from core.schemas import Artifact
    from specialists.optical_sar.dataset import OpticalSarPairedDataset
    from specialists.optical_sar.query_intent import QueryIntentInterpreter, FiLMQueryModulator

    print("\nSOURCE IMPORTS SUCCESSFUL")

if __name__ == "__main__":
    sync_and_verify()
